internal bool CanRegisterUserData(IBuilder builder, IUnRedoOperation unRedoOperation)
{
	IUnRedoDataDone<UnRedo_UserData> unRedoDone = unRedoOperation as IUnRedoDataDone<UnRedo_UserData>;
	if (builder.Actions.FirstOrDefault((IUnRedoActionOperation p) => p is IUnRedoDataDone<UnRedo_UserData> unRedoDataDone && unRedoDataDone.Data.IsAllUserData && unRedoDataDone.Data.ModuleFullName == unRedoDone.Data.ModuleFullName) != null)
	{
		return false;
	}
	IRootParam rootParam = builder as IRootParam;
	if (rootParam.RootOperType != "ModifyConfig" && rootParam.RootOperType != "DeleteModule" && rootParam.RootOperType != "CopyModule")
	{
		return false;
	}
	if (unRedoDone.Data.OldValue is Expression<Func<object>> expression)
	{
		unRedoDone.Data.OldValue = expression.Compile()();
	}
	return true;
}

